function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORE_TABLE = 1;  // 店舗マスタ
  const PRODUCT_TABLE = 2; // 商品マスタ
  const ORDER_TABLE = 7;   // 発注データ

  let currentOrders = [];
  let stores = [];
  let products = [];

  // 現在日時を表示
  function updateOrderDate() {
    const now = new Date();
    const dateStr = now.getFullYear() + '年' + 
                   String(now.getMonth() + 1).padStart(2, '0') + '月' + 
                   String(now.getDate()).padStart(2, '0') + '日';
    container.querySelector('#order-date').textContent = dateStr;
  }

  // 発注データテーブル再描画
  function renderOrderRows(orders) {
    const tbody = container.querySelector('#order-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" style="text-align: center; padding: 2rem; color: var(--text-muted);">
            発注対象のデータがありません
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const product = products.find(p => p.商品ID === order.商品ID) || {};
      const statusBadge = getStatusBadge(order.発注ステータス);
      const amount = (order.発注数量 || 0) * (order.発注単価 || 0);

      return `
        <tr data-id="${order.発注ID}">
          <td style="text-align: center;">
            <input type="checkbox" class="order-checkbox" data-id="${order.発注ID}" 
                   ${order.発注ステータス === '送信済' ? 'disabled' : ''}>
          </td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td style="text-align: right;">${order.予測数量 || 0}</td>
          <td style="text-align: right;">${order.発注数量 || 0}</td>
          <td>${order.仕入先名 || ''}</td>
          <td style="text-align: right;">¥${amount.toLocaleString()}</td>
          <td>${statusBadge}</td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
  }

  // ステータスバッジ生成
  function getStatusBadge(status) {
    const badges = {
      '発注済': '<span style="background: #ffa500; color: white; padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">発注済</span>',
      '送信済': '<span style="background: #44aa44; color: white; padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">送信済</span>',
      '送信待ち': '<span style="background: #ff6a00; color: white; padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">送信待ち</span>',
      'キャンセル': '<span style="background: #888; color: white; padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">キャンセル</span>'
    };
    return badges[status] || `<span style="background: var(--text-muted); color: white; padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">${status}</span>`;
  }

  // 合計金額更新
  function updateTotalAmount() {
    const checkboxes = container.querySelectorAll('.order-checkbox:checked:not(:disabled)');
    let total = 0;
    let count = 0;

    checkboxes.forEach(cb => {
      const orderId = cb.dataset.id;
      const order = currentOrders.find(o => o.発注ID === orderId);
      if (order) {
        total += (order.発注数量 || 0) * (order.発注単価 || 0);
        count++;
      }
    });

    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
    container.querySelector('#selected-count').textContent = count;

    // 送信ボタンの有効/無効制御
    const sendBtn = container.querySelector('#btn-send');
    sendBtn.disabled = count === 0;
  }

  // 店舗選択肢を読み込み
  async function loadStores() {
    const storeData = await window.aivicApi.list(STORE_TABLE);
    if (storeData) {
      stores = storeData.filter(s => s.有効フラグ);
      const select = container.querySelector('#store-select');
      select.innerHTML = '<option value="">店舗を選択してください</option>' +
        stores.map(store => 
          `<option value="${store.店舗ID}">${store.店舗名} (${store.店舗コード})</option>`
        ).join('');
    }
  }

  // 商品マスタを読み込み
  async function loadProducts() {
    const productData = await window.aivicApi.list(PRODUCT_TABLE);
    if (productData) {
      products = productData;
    }
  }

  // 店舗別発注データを読み込み
  async function loadOrdersByStore(storeId) {
    if (!storeId) {
      currentOrders = [];
      renderOrderRows([]);
      return;
    }

    const orderData = await window.aivicApi.list(ORDER_TABLE);
    if (orderData) {
      // 選択店舗の発注データのみフィルタ（送信待ち・発注済のみ）
      currentOrders = orderData.filter(order => 
        order.店舗ID === storeId && 
        ['発注済', '送信待ち'].includes(order.発注ステータス)
      );
      renderOrderRows(currentOrders);
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    successDiv.textContent = message;
    successDiv.classList.remove('hidden');
    setTimeout(() => successDiv.classList.add('hidden'), 3000);
  }

  // 発注送信処理
  async function sendOrders() {
    const checkboxes = container.querySelectorAll('.order-checkbox:checked:not(:disabled)');

    if (checkboxes.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    const orderIds = Array.from(checkboxes).map(cb => cb.dataset.id);
    const ordersToSend = currentOrders.filter(o => orderIds.includes(o.発注ID));

    // 送信済みデータの重複チェック
    const alreadySent = ordersToSend.filter(o => o.発注ステータス === '送信済');
    if (alreadySent.length > 0) {
      showError('この発注データは既に送信済みです。重複送信はできません。');
      return;
    }

    try {
      // 各発注データのステータスを「送信済」に更新
      let successCount = 0;
      for (const order of ordersToSend) {
        const updated = await window.aivicApi.update(ORDER_TABLE, order.発注ID, {
          発注ステータス: '送信済',
          更新日時: new Date().toISOString(),
          更新者ID: 'current-user-id' // 実際の実装では現在のユーザーIDを使用
        });

        if (updated) {
          successCount++;
        }
      }

      if (successCount > 0) {
        showSuccess(`${successCount}件の発注データを正常に送信しました`);
        // データを再読み込み
        const storeId = container.querySelector('#store-select').value;
        await loadOrdersByStore(storeId);
        // 全選択チェックボックスをリセット
        container.querySelector('#select-all').checked = false;
      } else {
        showError('発注送信に失敗しました');
      }
    } catch (error) {
      showError('ネットワークエラーが発生しました。接続を確認してください。');
    }
  }

  // 初期化処理
  async function initialize() {
    updateOrderDate();
    await loadStores();
    await loadProducts();

    // 初期データがある場合は表示
    if (tables[ORDER_TABLE] && tables[ORDER_TABLE].records) {
      currentOrders = tables[ORDER_TABLE].records.filter(order => 
        ['発注済', '送信待ち'].includes(order.発注ステータス)
      );
    }
  }

  // イベントリスナー設定

  // 店舗選択変更
  container.querySelector('#store-select').addEventListener('change', async (e) => {
    const storeId = e.target.value;
    if (!storeId) {
      showError('指定された店舗が存在しません');
      return;
    }
    await loadOrdersByStore(storeId);
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.order-checkbox:not(:disabled)');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateTotalAmount();
  });

  // 個別チェックボックス（イベントデリゲーション）
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('order-checkbox')) {
      updateTotalAmount();

      // 全選択チェックボックスの状態更新
      const allCheckboxes = container.querySelectorAll('.order-checkbox:not(:disabled)');
      const checkedCheckboxes = container.querySelectorAll('.order-checkbox:checked:not(:disabled)');
      const selectAllCb = container.querySelector('#select-all');

      if (checkedCheckboxes.length === 0) {
        selectAllCb.indeterminate = false;
        selectAllCb.checked = false;
      } else if (checkedCheckboxes.length === allCheckboxes.length) {
        selectAllCb.indeterminate = false;
        selectAllCb.checked = true;
      } else {
        selectAllCb.indeterminate = true;
      }
    }
  });

  // 送信ボタン
  container.querySelector('#btn-send').addEventListener('click', () => {
    const checkboxes = container.querySelectorAll('.order-checkbox:checked:not(:disabled)');
    const count = checkboxes.length;

    if (count === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    // 合計金額計算
    let total = 0;
    checkboxes.forEach(cb => {
      const orderId = cb.dataset.id;
      const order = currentOrders.find(o => o.発注ID === orderId);
      if (order) {
        total += (order.発注数量 || 0) * (order.発注単価 || 0);
      }
    });

    // 確認モーダル表示
    container.querySelector('#confirm-count').textContent = count;
    container.querySelector('#confirm-amount').textContent = `¥${total.toLocaleString()}`;
    container.querySelector('#send-modal').style.display = 'block';
  });

  // モーダル操作
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    container.querySelector('#send-modal').style.display = 'none';
  });

  container.querySelector('#btn-confirm').addEventListener('click', async () => {
    container.querySelector('#send-modal').style.display = 'none';
    await sendOrders();
  });

  // モーダル背景クリックで閉じる
  container.querySelector('#send-modal').addEventListener('click', (e) => {
    if (e.target.id === 'send-modal') {
      container.querySelector('#send-modal').style.display = 'none';
    }
  });

  // 初期化実行
  initialize();
}
